pn={"s":(80,110,"i: 0\npc: start","accent"),"m":(320,50,"i: 42\npc: middle"),"m2":(320,170,"i: 43\npc: middle"),"d":(560,50,"i: 43\npc: done"),"d2":(560,170,"i: 44\npc: done")}
